class Solution {
  public int[] sortTransformedArray(int[] nums, int a, int b, int c) {
    int n = nums.length;
    int[] res = new int[n];
    // the parabola is largest at the ends when a >= 0, smallest at the ends when a < 0
    int lo = 0, hi = n - 1, k = a >= 0 ? n - 1 : 0;
    while (lo <= hi) {
      int fl = f(nums[lo], a, b, c), fh = f(nums[hi], a, b, c);
      if (a >= 0) {
        if (fl >= fh) {
          res[k--] = fl;
          lo++;
        } else {
          res[k--] = fh;
          hi--;
        }
      } else {
        if (fl <= fh) {
          res[k++] = fl;
          lo++;
        } else {
          res[k++] = fh;
          hi--;
        }
      }
    }
    return res;
  }

  private int f(int x, int a, int b, int c) {
    return a * x * x + b * x + c;
  }
}
